        assertEquals("Jumlah harus lebih dari nol", e.getMessage());
    }
}

class Rekening {
    private int saldo;

    Rekening(int saldo) {
        this.saldo = saldo;
    }

    int getSaldo() {
        return saldo;
    }

    void tarik(int jumlah) {
        if (jumlah <= 0) {
            throw new IllegalArgumentException("Jumlah harus lebih dari nol");
        }
        if (jumlah > saldo) {
            throw new IllegalArgumentException("Saldo tidak cukup");
        }
        saldo -= jumlah;
    }
}
